$ErrorActionPreference='Stop';$taskChild=Join-Path $PSScriptRoot 'child-writer.ps1';Start-Process -WindowStyle Hidden -WorkingDirectory $PSScriptRoot -FilePath (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',('"'+$taskChild+'"')) | Out-Null;$p=Get-Process -Id $PID;@{kind='os';pid=$PID;created=$p.StartTime.ToUniversalTime().ToFileTimeUtc().ToString('x16');executable=$p.Path.ToLowerInvariant()}|ConvertTo-Json -Compress | Set-Content -LiteralPath (Join-Path $PSScriptRoot 'parent.json') -Encoding UTF8;Start-Sleep -Seconds 55